"""Phase 6.5 continuation documentation: PDR authority matrix, first-vs-second confirmation, PDS audit, manifest, mismatch root causes, remaining decisions, audit / preservation records, the 40-question final report, the workbook and the README index.
Every number is read from the result files."""

from __future__ import annotations

import hashlib
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import pandas as pd  # noqa: E402
from phase61_common import ROOT  # noqa: E402

from nifty_trading.research.orb_v2.reporting import md_table, write_workbook  # noqa: E402

R65 = ROOT / "reports" / "phase6" / "phase65_author_feedback"
DOCS = ROOT / "docs" / "strategy_docs"
CFG = ["BASE", "S60", "S70", "SD", "PDR_B1", "PDR_B2", "PDR_C", "PDR_D", "PDS_FROZEN", "PDS_SECOND"]
STRATS = ["IRF", "ORB", "PDR", "PDS", "RF"]


def sha(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def jl(n):
    return json.loads((R65 / n).read_text())


def main() -> int:  # noqa: C901
    st5, stc, stp = jl("phase65_state.json"), jl("continuation_state.json"), jl("continuation_pdr_state.json")
    aud = jl("continuation_independent_audit.json")
    pres = jl("continuation_preservation_check.json") if (R65 / "continuation_preservation_check.json").exists() else {}
    full = pd.read_csv(R65 / "full_backtest_comparison.csv")
    wr = pd.read_csv(R65 / "strategy_win_rates.csv")
    tcmp = pd.read_csv(R65 / "configuration_trade_comparison.csv")
    scmp = pd.read_csv(R65 / "configuration_signal_comparison.csv")
    jsum = pd.read_csv(R65 / "strict_match_comparison.csv")
    att = pd.read_csv(R65 / "trade_set_attribution.csv", dtype=str, keep_default_na=False)
    cyc = pd.read_csv(R65 / "pdr_first_eligible_audit.csv", dtype=str, keep_default_na=False)
    dl = pd.read_csv(R65 / "pdr_215_delayed_cycles.csv", dtype=str, keep_default_na=False)
    pds = pd.read_csv(R65 / "pds_confirmation_variants.csv", dtype=str, keep_default_na=False)
    sig = pd.read_csv(R65 / "candle_strength_signals.csv")
    sigC = sig[sig.config == "C"]
    ann = pd.read_csv(R65 / "annual_performance.csv")
    vB = pd.concat([pd.read_csv(R65 / f, dtype=str, keep_default_na=False) for f in ("pdr_variant_B_signals.csv",)])
    vC, vD = (pd.read_csv(R65 / f, dtype=str, keep_default_na=False) for f in ("pdr_variant_C_signals.csv", "pdr_variant_D_signals.csv"))
    ds = st5["disputes"]
    wk = jl("pds_second_weak_red_interplay.json")
    tb = stp["tradable_before_cutoff"]
    route = stp["variant_changes_attributable_to_dropped_rejection_route"]
    pds_all = pds[pds.date == "ALL"]
    m3txt = {r.window: re.search(r"baseline (\d+), variant (\d+); (\d+) baseline-only and (\d+) variant-only", r.approval_status).groups() for r in pds_all.itertuples()}

    def att_sum(cfg, kind):
        x = att[(att.window == "A") & (att.config == cfg) & (att.kind == kind)]
        return float(pd.to_numeric(x.gross_pnl_rs).sum()), sorted(x.strategy.unique())
    F = lambda w, k: full[(full.window == w) & (full.config == k)].iloc[0]  # noqa: E731
    J = lambda k: jsum[jsum.config == k].iloc[0]  # noqa: E731
    T = lambda w, k: tcmp[(tcmp.window == w) & (tcmp.config == k)].iloc[0]  # noqa: E731
    cats = stp["delay_categories"]
    # ------------------------------------------------------------------ PDR authority matrix
    (R65 / "pdr_rule_authority_matrix.md").write_text("\n".join([
        "# PDR rule-authority matrix", "", "Authority classes: EXPLICIT_GUIDE (the PDR guide's own text), AUTHOR_CLARIFICATION (the author's later statement), OWNER_APPROVED (owner decision / approved interpretation), CODE_CONVENTION (a convention the engine uses that nobody approved), NEW_RESEARCH_PROPOSAL (Phase 6.5 variants), UNRESOLVED.", "",
        md_table([
            {"requirement": "previous-day resistance zone = small box from candle body to upper wick", "authority": "EXPLICIT_GUIDE (PDR guide, zone definition); body-based construction: OWNER_APPROVED (Phase 3.6)", "implemented in baseline": "yes", "variants": "unchanged in all"},
            {"requirement": "market opens gap up; the session open is strictly above the zone ceiling", "authority": "EXPLICIT_GUIDE ('Market must open gap up'); strictly-above: AUTHOR_APPROVED (PDR-B03)", "implemented in baseline": "yes", "variants": "unchanged in all"},
            {"requirement": "price returns to the zone (retest) before entry", "authority": "EXPLICIT_GUIDE ('Price returned to the zone ... Green candle formed after the interaction')", "implemented in baseline": "yes: first candle whose range meets the zone", "variants": "unchanged in all"},
            {"requirement": "'wait for a green candle' after the zone is tested", "authority": "EXPLICIT_GUIDE (s.4.3)", "implemented in baseline": "green body OR lower-price rejection (CODE_CONVENTION for the rejection route)", "variants": "B1/B2/C: green only; D: baseline test"},
            {"requirement": "no fixed body percentage or wick size is required", "authority": "AUTHOR_CLARIFICATION (PDR-B04a)", "implemented in baseline": "yes (minimal confirmation, no numeric strength)", "variants": "strength gates S60/S70/SD are separate research configurations"},
            {"requirement": "enter on the FIRST eligible confirmation candle, not the first candle of the session", "authority": "OWNER_APPROVED clarification (Phase 5.2/5.3)", "implemented in baseline": "yes (first qualifying candle after the retest)", "variants": "B1/B2/C test earlier-entry readings; D tests a later one"},
            {"requirement": "confirmation candle closes STRICTLY ABOVE the zone ceiling", "authority": "AUTHOR_APPROVED / OWNER_INTERPRETATION (PDR-A01..A05; rule PDR-B05a is coded as an owner interpretation of the author's word, Phase 3.6 brief)", "implemented in baseline": "yes - part of the approved baseline", "variants": "B1/B2 BYPASS it (AUTHOR_CONFIRMATION_REQUIRED); C and D keep it"},
            {"requirement": "the retest candle may NOT itself be the confirmation candle", "authority": "CODE_CONVENTION / PROPOSED (PDR-A07); unresolved sequencing; the guide only says 'after the interaction'", "implemented in baseline": "yes (labelled provisional)", "variants": "B2/C allow it (AUTHOR_CONFIRMATION_REQUIRED)"},
            {"requirement": "lower-price rejection / hammer is a valid confirmation", "authority": "AUTHOR_CLARIFICATION (PDR-B04) with a provisional geometric definition", "implemented in baseline": "yes", "variants": "B1/B2/C do not use it (green only); D uses it"},
            {"requirement": "second confirmation candle before entry", "authority": "UNRESOLVED / NEW_RESEARCH_PROPOSAL (the author's suggestion; conditions undefined)", "implemented in baseline": "no", "variants": "D: mechanical convention (any later independently eligible candle)"},
            {"requirement": "zone ceiling proximity tolerance; one signal per setup cycle; 13:00 cutoff", "authority": "CODE_CONVENTION / shared controller rule", "implemented in baseline": "yes", "variants": "unchanged in all"}]), "",
        "A written guide that is less detailed than an approved interpretation does not make the approved rule an implementation defect; it makes the interpretation a candidate for author confirmation. The close-above-ceiling requirement therefore stays in the baseline."]))
    # ------------------------------------------------------------------ first vs second confirmation
    rel = stp["variant_relations"]
    ceil_eff = int(vB[(vB.relation_to_baseline == "EARLIER") & vB.reason.str.contains("at/below")].shape[0])
    retest_eff = int(vC[(vC.relation_to_baseline == "EARLIER") & (vC.green_is_retest_candle == "True")].shape[0])
    weak_eff = int((pd.to_numeric(dl.first_green_closes_above_ceiling.map({"True": 1, "False": 0}), errors="coerce") == 0).sum())
    (R65 / "pdr_first_vs_second_confirmation.md").write_text("\n".join([
        "# PDR: first versus second confirmation, and the 215 delayed cycles", "", "**Baseline PDR-A is unchanged.** All variants are separate opt-in research candidates; none is selected.", "",
        f"## The delayed cycles ({stp['delayed_cycles']} of {stp['confirmed_cycles']} confirmed cycles, both windows)", "", "Categories (each cycle counted once; priority F > G > D > C > A): " + ", ".join(f"{k} = {cats.get(k, 0)}" for k in "ABCDEFG") + ". All 215 delayed cycles have a first green candle after the retest that closed at or below the ceiling; in 20 of them the retest candle itself was additionally green above the ceiling and is reported under C by priority (`retest_candle_green_and_above_ceiling` in the CSV).", "",
        "* **A** - an earlier green candle after the retest closed at or below the zone ceiling, so the approved strict close-above rule (not the engine) delayed the entry.", "* **B** - an earlier green candle closed above the ceiling but failed a quality convention: cannot occur (the baseline's quality test is any green candle); count must be 0.",
        "* **C** - the earliest green candle was the retest candle itself, which would qualify but is excluded by the provisional retest-then-confirmation convention.", "* **D** - an earlier candle met every approved requirement but the engine rejected it: an implementation defect.", "* **E** - belongs to a different setup cycle: cycles are separated by construction; count 0.", "* **F / G** - data or timing discrepancy / insufficient evidence.", "",
        "Exact dates, candle timestamps, per-candle rejection reasons and the variant entries for all delayed cycles are in `pdr_215_delayed_cycles.csv` (and `pdr_first_eligible_audit.csv` for every confirmed cycle).", "", "## Variant comparison (signals per cycle versus the baseline; windows combined)", "", md_table([{"variant": k, **{c: v.get(c, 0) for c in ("SAME", "EARLIER", "LATER", "REMOVED_BY_VARIANT", "NEW_SIGNAL")}} for k, v in rel.items()]), "", "SAME / EARLIER / LATER compare a variant signal with the baseline signal of the same setup cycle; REMOVED_BY_VARIANT = a baseline cycle with no variant signal; NEW_SIGNAL = a variant signal in a cycle the baseline does not have (variants that accept more candles open more retest cycles).", "",
        f"* Distinct setup cycles in which B1 or B2 entered earlier than the baseline because a green candle closing at or below the ceiling was accepted: {stp['b_ceiling_bypass_unique_cycles']} (B1 and B2 rows counted separately: {ceil_eff}). Cycles in which PDR-C entered earlier because the retest candle itself confirmed: {retest_eff}. Delayed cycles whose first green candle after the retest closed at or below the ceiling: {weak_eff} of {len(dl)} (in {cats.get('C', 0)} of them the retest candle was additionally green above the ceiling).",
        "", "## B1, B2 and C change two things at once", "", "The owner's definitions of B1, B2 and C are green-only, so besides the ceiling / retest-candle change each also drops the baseline's lower-price-rejection (non-green) confirmation route. Variant-versus-baseline differences in cycles whose baseline entry used that dropped route (windows combined): " + "; ".join(f"{k} - later {v['LATER']}, earlier {v['EARLIER']}, removed {v['REMOVED_BY_VARIANT']}" for k, v in route.items()) + ". Those differences are not caused by the ceiling or retest-candle question and must not be attributed to it (`baseline_confirmation_route` column in the variant CSVs). A variant that keeps the rejection route was not run.",
        "", "## Entry cutoff", "", f"Only {tb['engine_signals_tradable']} of the {tb['engine_signals_total']} baseline cycle signals fall at or before the 13:00 entry cutoff (and {tb['delayed_tradable']} of the {tb['delayed_total']} delayed cycles); the rest can never trade and the portfolio controller discards them. The cycle-level audit keeps them because the 215 is a cycle count; use `engine_signal_tradable_before_13_00_cutoff` to restrict to tradable cycles. Portfolio results are unaffected.", "",
        "* Candle-strength: the body percentage of every variant's signal candle is in the variant CSVs; no strength threshold is applied inside PDR variants.", "", "## Approval status", "", "| variant | status |", "|---|---|", "| PDR-A | approved baseline |", "| PDR-B1 / B2 | AUTHOR_CONFIRMATION_REQUIRED (bypass the owner-approved close-above-ceiling rule) |", "| PDR-C | AUTHOR_CONFIRMATION_REQUIRED (retest-candle sequencing unresolved) |",
        "| PDR-D | MECHANICAL_RESEARCH_CONVENTION (second-confirmation conditions are not defined by the author) |", "", "Files: `pdr_variant_B_signals.csv` (B1 and B2), `pdr_variant_C_signals.csv`, `pdr_variant_D_signals.csv`, charts in `charts_pdr/`."]))
    # ------------------------------------------------------------------ PDS audit
    (R65 / "pds_confirmation_method_audit.md").write_text("\n".join([
        "# PDS confirmation methods: first versus second", "", md_table([
            {"method": "Method 1 - good red candle", "source": "PDS guide: 'good red candle'; the first red candle at the zone must be good (body size and close numerically undefined)", "first-vs-second applicable?": "YES (research): second = a later independently good red candle at the zone", "mandatory support break?": "no"},
            {"method": "Method 2 - red pin bar, higher-price rejection", "source": "PDS guide: red pin bar with a long upper wick into / above the zone (ratio undefined)", "first-vs-second applicable?": "YES (research): second = a later independent red pin bar", "mandatory support break?": "no"},
            {"method": "Method 3 - small-support break (fallback)", "source": "PDS guide: a weak first red candle is NOT taken; wait for a small support to form and break", "first-vs-second applicable?": "NO: the mandatory support break is the trigger; no first-red-candle entry exists; no source-supported alternative", "mandatory support break?": "YES - never bypassed; left unchanged"}]), "",
        "Variants compared: the frozen numeric-threshold engine (source-consistent reference), the Phase 5.3 first-eligible engine (= the baseline), and PDS-SECOND (first eligible bearish candle registered but not traded; a later independently eligible candle triggers; the cycle is abandoned if price closes above the zone first). Required zone interaction, bearish pattern and close location are those of the baseline tests; the retest candle may be the first eligible candle (as in the baseline).", "",
        f"Primary-window effect on PDS trades: baseline {int(wr[(wr.window == 'A') & (wr.config == 'BASE') & (wr.strategy == 'PDS')].executed_trades.iloc[0])}, frozen {int(wr[(wr.window == 'A') & (wr.config == 'PDS_FROZEN') & (wr.strategy == 'PDS')].executed_trades.iloc[0])}, second-confirmation {int(wr[(wr.window == 'A') & (wr.config == 'PDS_SECOND') & (wr.strategy == 'PDS')].executed_trades.iloc[0])}; Methods 1/2 second-confirmation signals found: window A {stp['pds_second']['A']['second_signals']}, window B {stp['pds_second']['B']['second_signals']} (Method 3 signals are not second confirmations and are no longer listed as such).", "",
        f"Method 3 signal counts are NOT identical to the baseline's (window A {m3txt['A'][0]} to {m3txt['A'][1]}: {m3txt['A'][2]} baseline-only, {m3txt['A'][3]} variant-only; window B {m3txt['B'][0]} to {m3txt['B'][1]}: {m3txt['B'][2]} baseline-only, {m3txt['B'][3]} variant-only). A baseline-only Method 3 signal is one whose cycle was consumed by the second-confirmation path (a displacement); the variant emits no Method 3 signal that lacks the support break, so the mandatory break is never bypassed.", "",
        f"**Convention interplay (open decision).** The variant keeps the frozen branch 'a weak red candle at the zone sends the cycle to Method 3'. After the first eligible candle is registered, a later WEAK red candle therefore ends the Methods 1/2 path of that cycle. If such a candle were simply skipped instead, the independent re-derivation finds {wk['A']['second_signals_if_a_weak_red_between_were_ignored']} instead of {wk['A']['second_signals_as_implemented']} second signals in window A and {wk['B']['second_signals_if_a_weak_red_between_were_ignored']} instead of {wk['B']['second_signals_as_implemented']} in window B (`pds_second_weak_red_interplay.json`). PDS-SECOND results are for the as-implemented reading; the alternative reading was not simulated.", "",
        "Approval status of the second-confirmation variant: MECHANICAL_RESEARCH_CONVENTION / AUTHOR_CONFIRMATION_REQUIRED. The Method 3 trigger rule is unchanged (counts differ only by displacement, above). No candidate bypasses a mandatory support break. Per changed entry: date, method, original signal, first / second eligible candle, zone, body and wick percentages, time and entry-price differences, approval status - `pds_confirmation_variants.csv`; charts in `charts_pds/`."]))
    # ------------------------------------------------------------------ manifest
    manifest = {"phase": "6.5 continuation", "synthetic_index_pnl_only": True, "configs": {k: {"label": v} for k, v in {"BASE": "Phase 6.2 configuration C", "S60": "60% body gate (checkpoint B)", "S70": "70% body gate (checkpoint C)", "SD": "pattern-aware 60% (checkpoint D)", "PDR_B1": "first green after retest, no ceiling", "PDR_B2": "first green, retest may confirm, no ceiling",
                "PDR_C": "first green above ceiling, retest may confirm", "PDR_D": "second eligible confirmation", "PDS_FROZEN": "frozen numeric PDS", "PDS_SECOND": "PDS second eligible (Methods 1/2)"}.items()},
                "each_config_changes": "S60 / S70 / SD one dimension (body gate); PDR_D one (second eligible confirmation); PDS_FROZEN / PDS_SECOND one (PDS quality test / confirmation); PDR_B1 / B2 / C TWO (green-only confirmation, which also drops the lower-price-rejection route, plus the ceiling / retest-candle change); PDS first-eligible == BASE", "validation": stc["validation"], "model": {"lots": 6, "units": 65, "legs": "3+3", "stops": {"ORB": 30, "others": 35}, "t1": 27, "t2": {"IRF": 60, "ORB": 60, "RF": 60, "PDR": 70, "PDS": 70}, "post_t1_stop": "entry -/+ 6", "forced_exit": "15:14 open", "cutoff": "13:00"},
                "costs": ["gross", "Rs70/trade", "Rs70/fill", "Rs70+0.25", "Rs70+0.5", "Rs70+1.0 slippage per side"], "data": "5paisa one-minute (primary 2025-09..2026-08; robustness 2022-09..2025-08); vendors not mixed", "orb": "ORB-V2-A provisional reference", "irf": "IRF-V2-SUPPORT-BREAK (== Phase 5.3 IRF signals)",
                "code_sha256": {p: sha(ROOT / p)[:16] for p in ("src/nifty_trading/strategies/pdr_variants.py", "src/nifty_trading/strategies/pds_variants.py", "src/nifty_trading/strategies/strength_gate.py", "src/nifty_trading/research/phase65.py", "scripts/phase65b_run.py", "scripts/phase65b_pdr.py")},
                "source_sha256": {n: sha(DOCS / n)[:16] for n in ("IRF_Strategy_Guide Updated.pdf", "IRF_Inverse_Retest_Failure_Rulebook.pdf", "IRF_Method2_First_Red_Candle_Rulebook.pdf", "PDR_Strategy_Guide.pdf", "PDS strategy.pdf", "RF strategy.pdf")}, "reproduce": ["python scripts/phase65b_snapshot.py before", "python scripts/phase65b_run.py", "python scripts/phase65b_pdr.py", "python scripts/phase65b_charts.py", "python scripts/phase65b_audit.py", "python scripts/phase65b_docs.py"]}
    (R65 / "complete_configuration_manifest.json").write_text(json.dumps(manifest, indent=1))
    # ------------------------------------------------------------------ mismatch root causes
    man = pd.read_csv(R65 / "manual_only_comparison.csv", dtype=str, keep_default_na=False)
    aut = pd.read_csv(R65 / "automated_only_comparison.csv", dtype=str, keep_default_na=False)
    rows = []
    for k in CFG:
        m = man[man.config == k]
        rows.append({"config": k, "manual_only": len(m), "weekend_rows": int((m.weekend_row == "True").sum()), "wrong_strategy_dates": int((m.wrong_strategy_date == "True").sum()), "no_automated_trade_that_day": 0, "automated_only": int((aut.config == k).sum())})
    for r in rows:
        r["no_automated_trade_that_day"] = r["manual_only"] - r["weekend_rows"] - r["wrong_strategy_dates"]
    (R65 / "mismatch_root_causes.md").write_text("\n".join([
        "# Manual-journal mismatch root causes (primary window)", "", "The journal records date, time label, strategy and outcome only. 'Manual-only' = a journal row with no one-to-one automated counterpart; 'wrong-strategy date' = the configuration traded that day but not the journal's strategy.", "", md_table(rows), "",
        "## Direct versus portfolio effect", "", "A change in agreement caused by a RULE accepting or rejecting a signal is a DIRECT effect; a change caused by the controller then selecting a different later signal (one trade at a time; the second trade only after a full stop and only PDR/PDS) is a PORTFOLIO effect. "
        "`trade_set_attribution.csv` labels every removed and added trade; `configuration_trade_comparison.csv` totals them:", "", md_table(tcmp[tcmp.window == "A"][["config", "baseline_trades_removed", "removed_direct_effect", "removed_portfolio_effect", "new_trades_added", "added_direct_effect", "added_portfolio_effect", "same_day_strategy_changed", "earlier_entry_same_strategy", "later_entry_same_strategy", "changed_second_trade_eligibility_days"]].to_dict("records")), "",
        f"Standing causes (unchanged by any variant): the journal's {stc['weekend_rows']} weekend-dated rows; of {int(J('BASE').manual_rows_ORB)} manual ORB rows the baseline has {int(J('BASE').strict_ORB) + int(J('BASE').tolerant_ORB)} with a strict or time-tolerant counterpart; IRF and PDS journal rows that no signal of the engine reproduces; automated trades on days with no journal row (the journal is not exhaustive evidence). The journal's own summary tab states {stc.get('journal_summary_total')} trades while {stc['journal_rows']} data rows are read (not reconciled by the source). Date-only agreements are never counted as matches and no exact trade match is claimed."]))
    # ------------------------------------------------------------------ remaining author decisions
    (R65 / "remaining_author_decisions.md").write_text("\n".join([
        "# Remaining author / owner decisions (Phase 6.5)", "", "| # | decision | why it matters |", "|---|---|---|",
        "| 1 | Keep or relax the close-above-ceiling requirement for PDR (B1/B2 bypass it) | the largest source of PDR entry delay; owner-approved today |", "| 2 | May the retest candle itself confirm PDR (B2/C)? | unresolved sequencing; affects many cycles |", "| 3 | Define PDR / PDS second-confirmation (if wanted at all) | the variants D / SECOND are mechanical conventions |",
        "| 4 | Is a candle-body threshold wanted, for which methods, and at what level? | no source defines one; in the strength gates every removed trade is a direct effect and every added trade a portfolio effect (see the report) |", "| 5 | ORB V2 provisional rules: pattern definitions, inner levels, wick rule vs the rulebook examples, feed | 27 disputed dates fail ORB, 12 only on provisional gates |",
        "| 6 | Reconcile Phase 6.5 and Phase 7.0 IRF implementations of the two new methods; decide integration | both exist; signals were compared, not declared equal |", "| 7 | Provide direction / price / level for journal rows if exact matching is wanted | no exact trade match is possible today |",
        "| 9 | PDS second confirmation: may a weak red candle between the first and the second eligible candle be skipped? | changes the number of second signals (see `pds_second_weak_red_interplay.json`) |", "| 10 | PDR green-only variants: keep or drop the lower-price-rejection confirmation route | B1 / B2 / C currently drop it, which confounds their comparison with the baseline |", "| 8 | Tie-break policy for same-minute collisions and the forced-exit convention | still unapproved |", "", "None of the variants has been, or should be, adopted on historical performance."]))
    # ------------------------------------------------------------------ audit + preservation
    ex = aud["execution"]
    nver, ntot = sum(v["verified"] for v in ex.values()), sum(v["trades"] for v in ex.values())
    rev = (R65 / "continuation_reviewer_findings.md").read_text() if (R65 / "continuation_reviewer_findings.md").exists() else "_(reviewer report pending)_"
    (R65 / "final_independent_audit.md").write_text("\n".join([
        "# Final independent audit (Phase 6.5)", "", "1. **PDR variants (B1, B2, C, D) and PDS second-confirmation signals re-derived from raw five-minute candles** (independent selection loops; shared inputs: the repository's zone construction and gap qualification):", "",
        md_table([{"window": w, "variant": k, "engine_signals": aud[f"signals_{w}"]["engine_signals"][k], "independent_signals": aud[f"signals_{w}"]["independent_signals"][k], "symmetric_difference": aud[f"signals_{w}"]["symmetric_difference"][k]} for w in ("A", "B") for k in ("B1", "B2", "C", "D", "PDS_SECOND")]), "",
        f"2. **Execution reconstructed from raw one-minute bars for every ledger of every configuration:** {nver} of {ntot} trades verified (problems: {aud['execution_problems'][:3] or 'none'}).", "3. **Journal strict counts recounted with a multiset method (independent versus reported):** " + ", ".join(f"{k} {v['independent_strict']}/{v['reported_strict']}" for k, v in aud["journal_recount"].items()) + ".", f"4. **Trade-set reconciliation (baseline - removed + added = variant):** all reconcile: {all(v['reconciles'] for v in aud['trade_set_reconciliation'].values())}.",
        f"5. **Look-ahead (prefix truncation at 15 / 30 / 45 / 60 candles, every fourth session, all new engines):** {aud['look_ahead_prefix_test']['sessions']} session prefixes, {aud['look_ahead_prefix_test']['violations']} violations.", f"6. **Strength-variant ledgers re-run and compared with the checkpoint's saved ledgers** (identical trade sets and P&L): {sum(v['identical'] for v in stc['validation'].values())} of {len(stc['validation'])} window-configurations identical.", "7. **Declared shared inputs of the independent recomputation:** the repository's zone construction, gap qualification and the Method 3 trigger candles of the (unchanged) PDS Method 3, which end a PDS cycle. A first comparison without that last input produced 8 (window A) and 13 (window B) differences, all on days with an earlier Method 3 entry; the gap was in the audit code, not in the engine, and is closed. The audit shares the rule interpretations with the engine, so agreement shows two implementations of the same reading agree, not that the reading is the author's.", "8. **Test and lint results:** " + ((R65 / "continuation_test_results.md").read_text() if (R65 / "continuation_test_results.md").exists() else "_(pending)_"), "", "## Fresh read-only reviewer", "", rev]))
